--- 加成改变通知客户端
---@param actor table 角色对象
---@param bonusType number 加成类型
---@param value number 加成值
---@param expireTime number 加成过期时间
---@param buffId number  buffId
function ExpBonus.changeBonus(actor, bonusType, value, expireTime, buffId)
    sendluamsg(actor, LuaMessageIdToClient.RES_EXP_BONUS_INFO, {
        bonusType = bonusType,
        value = value,
        expireTime = expireTime,
        buffId = buffId
    })
end
